reserved_word:
-- Quote the name with backticks wherever it is used:
SELECT `{word}` FROM ...;
-- or better, rename it once:
ALTER TABLE {table} RENAME COLUMN `{word}` TO {word}_value;

group_by_strict:
-- Group by every selected plain column, or summarise it:
SELECT customer_id, MAX(customer_name) AS customer_name, SUM(total)
FROM orders GROUP BY customer_id;

duplicate_key:
-- Save without failing when it already exists (upsert):
INSERT INTO {table} (...) VALUES (...)
ON DUPLICATE KEY UPDATE <column> = VALUES(<column>);

-- Only if it's the primary key after an import: move the counter past the data
SELECT MAX(id) + 1 FROM {table};
ALTER TABLE {table} AUTO_INCREMENT = <that number>;

fk_has_children:
-- Then choose: delete/move those rows first, or let the relation decide:
ALTER TABLE {child} DROP FOREIGN KEY {constraint};
ALTER TABLE {child} ADD CONSTRAINT {constraint} FOREIGN KEY ({column}) REFERENCES {table}({parent_column}) ON DELETE CASCADE;  -- or ON DELETE SET NULL

disk_full:
-- See what takes the space:
SELECT table_schema, ROUND(SUM(data_length+index_length)/1024/1024) AS mb FROM information_schema.tables GROUP BY table_schema ORDER BY mb DESC;
SHOW BINARY LOGS;

-- Remove old binary logs safely (keep what replicas still need):
PURGE BINARY LOGS BEFORE NOW() - INTERVAL 3 DAY;
SET GLOBAL binlog_expire_logs_seconds = 259200;

too_many_connections:
SHOW VARIABLES LIKE 'max_connections';
SHOW GLOBAL STATUS LIKE 'Threads_connected';
SHOW GLOBAL STATUS LIKE 'Max_used_connections';

-- Short term: SET GLOBAL max_connections = 300;  (and in my.cnf)
-- Real fix: a connection pool and closing connections; lower wait_timeout:
SET GLOBAL wait_timeout = 120;

connection_lost:
SHOW VARIABLES LIKE 'wait_timeout';
SHOW VARIABLES LIKE 'max_allowed_packet';
SHOW GLOBAL STATUS LIKE 'Uptime';  -- a small number = the server restarted recently

replication_stopped:
-- Duplicate entry (1062) or Can't find record (1032) on the replica = its data has drifted from the primary.
-- Compare that row on both servers ({table}), make the replica's row match the primary (take a backup first), then:
START REPLICA;   -- MariaDB/older: START SLAVE;
